begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
set local s1.tap='on';
select no_plan();
\ir s1_fixture.sql
insert into public.rooms(id,code,title,meeting_date,expires_at,owner_id)
values('20000000-0000-4000-8000-000000000004','S1CLOSED','Synthetic final completion',current_date+1,clock_timestamp()+interval '1 day','10000001-0000-4000-8000-000000000001');
insert into public.participants(room_id,profile_id,name) values('20000000-0000-4000-8000-000000000004','10000002-0000-4000-8000-000000000002','Synthetic B');
select pg_temp.prepare_confirmed_settlement('20000000-0000-4000-8000-000000000004');
set local role authenticated;
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
insert into pg_temp.s1_ids values('closed-final',public.create_room_settlement_v2('20000000-0000-4000-8000-000000000004','Synthetic final',2000,'Synthetic bank','0000','Synthetic A'));
select pg_temp.check(pg_temp.sqlstate_of($q$select public.set_settlement_completed((select id from public.dutch_pay_members where bill_id=(select v from pg_temp.s1_ids where k='closed-final') and profile_id=auth.uid()),false)$q$)='00000','open bill allows creator completion undo');
reset role;
insert into public.participants(room_id,profile_id,name) values('20000000-0000-4000-8000-000000000004','10000003-0000-4000-8000-000000000003','Synthetic late C');
set local role authenticated;
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select public.set_settlement_completed((select id from public.dutch_pay_members where bill_id=(select v from pg_temp.s1_ids where k='closed-final') and profile_id=auth.uid()),true);
select pg_temp.check(pg_temp.sqlstate_of($q$select public.set_settlement_completed((select id from public.dutch_pay_members where bill_id=(select v from pg_temp.s1_ids where k='closed-final') and profile_id=auth.uid()),false)$q$)='00000','open bill allows recipient completion undo');
select pg_temp.as_user('10000003-0000-4000-8000-000000000003');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.create_room_settlement_v2('20000000-0000-4000-8000-000000000004','Synthetic replacement',2000,'Other bank','1111','Synthetic C')$q$)='42501','late nonrecipient cannot replace an incomplete active settlement');
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.leave_room('20000000-0000-4000-8000-000000000004')$q$)='42501','incomplete open settlement still blocks owner leave');
select public.set_settlement_completed(id,true) from public.dutch_pay_members where bill_id=(select v from pg_temp.s1_ids where k='closed-final');
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.set_settlement_completed((select id from public.dutch_pay_members where bill_id=(select v from pg_temp.s1_ids where k='closed-final') and profile_id=auth.uid()),false)$q$)='S1005','closed bill rejects recipient undo with the app contract S1005');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.set_settlement_completed((select id from public.dutch_pay_members where bill_id=(select v from pg_temp.s1_ids where k='closed-final') and profile_id=auth.uid()),true)$q$)='00000','closed bill accepts idempotent completed true');
select pg_temp.as_user('10000001-0000-4000-8000-000000000001');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.set_settlement_completed((select id from public.dutch_pay_members where bill_id=(select v from pg_temp.s1_ids where k='closed-final') and profile_id='10000002-0000-4000-8000-000000000002'),false)$q$)='S1005','creator also cannot undo a closed recipient');
select pg_temp.check(not exists(select 1 from public.dutch_pay_members where bill_id=(select v from pg_temp.s1_ids where k='closed-final') and is_completed is not true),'failed undo leaves no incomplete members in the closed bill');
select pg_temp.check(public.leave_room('20000000-0000-4000-8000-000000000004')='deleted','rejected closed undo does not introduce a leave_room blocker');
select pg_temp.as_user('10000002-0000-4000-8000-000000000002');
select pg_temp.check(pg_temp.sqlstate_of($q$select public.set_settlement_completed((select id from public.dutch_pay_members where bill_id=(select v from pg_temp.s1_ids where k='closed-final') and profile_id=auth.uid()),false)$q$)='S1005','closed undo stays forbidden after room deletion');
select pg_temp.check(public.get_settlement_payment_details((select v from pg_temp.s1_ids where k='closed-final'))->>'status'='completed' and public.get_settlement_payment_details((select v from pg_temp.s1_ids where k='closed-final'))->'payment_details'='null'::jsonb,'closed snapshot stays completed without account contents');
reset role;
select pg_temp.check((select room_id is null and payment_disclosure_closed_at is not null and bank_name='' and account_number='' and account_holder='' from public.dutch_pay_bills where id=(select v from pg_temp.s1_ids where k='closed-final')),'room close preserves final bill without account values');
select * from finish();
rollback;
